import { DEFAULT_SETTINGS, mediaType, httpUrl, filename, isBlocked, originalName, suggestedName } from "./core.js";

let queue = Promise.resolve();
function serial(fn) { const task = queue.then(fn); queue = task.catch(console.error); return task; }
const key = tabId => `tab:${tabId}`;
const settings = async () => ({ ...DEFAULT_SETTINGS, ...(await chrome.storage.local.get("settings")).settings });

// Blob downloads need to keep the name generated by the HLS page through
// Chrome's final filename determination, including when Save As is enabled.
chrome.downloads.onDeterminingFilename.addListener((download, suggest) => {
  if (download.byExtensionId !== chrome.runtime.id || !download.url.startsWith("blob:")) {
    suggest();
    return;
  }
  const storageKey = `download-name:${download.url}`;
  chrome.storage.session.get(storageKey).then(data => {
    const name = data[storageKey];
    suggest(name ? {filename: name, conflictAction: "uniquify"} : undefined);
  }, () => suggest());
  return true;
});
async function badge(tabId, count) {
  try { await chrome.action.setBadgeBackgroundColor({ tabId, color: "#0d9488" }); await chrome.action.setBadgeText({tabId, text: count ? String(count) : ""}); } catch {}
}
async function collect(tabId, candidate) {
  if (tabId < 0 || !httpUrl(candidate.url)) return;
  const config = await settings();
  if (!config.enabled || isBlocked(candidate.url, config)) return;
  let tab;
  try { tab = await chrome.tabs.get(tabId); } catch { return; }
  if (isBlocked(tab.url, config)) return;
  const type = mediaType(candidate.url, candidate.mime);
  if (!type) return;
  const data = (await chrome.storage.session.get(key(tabId)))[key(tabId)] || { items: [], pageUrl: tab.url };
  const existing = data.items.find(item => item.url === candidate.url);
  const headerName = originalName("https://invalid/", candidate.disposition);
  let item = existing;
  if (!item) {
    if (data.items.length >= 150) return;
    item = { id: crypto.randomUUID(), url: candidate.url, type, mime: candidate.mime || "", size: 0, width: 0, height: 0, foundAt: Date.now() };
    data.items.push(item);
  }
  item.size = Math.max(item.size || 0, candidate.size || 0);
  item.width ||= candidate.width;
  item.height ||= candidate.height;
  if (headerName) item.headerName = headerName;
  const priority = Number(candidate.titlePriority) || 20;
  if (candidate.title && priority >= (item.videoTitlePriority || 0)) { item.videoTitle = String(candidate.title).slice(0, 300); item.videoTitlePriority = priority; }
  Object.assign(item, suggestedName(item, data.pageMetadata, tab.title));
  await chrome.storage.session.set({[key(tabId)]: data});
  await badge(tabId, data.items.length);
}

chrome.webRequest.onHeadersReceived.addListener(details => {
  if (details.tabId < 0 || details.statusCode < 200 || details.statusCode >= 300) return;
  const headers = Object.fromEntries((details.responseHeaders || []).map(h => [h.name.toLowerCase(), h.value]));
  const mime = headers["content-type"] || "";
  if (!mediaType(details.url, mime)) return;
  const total = headers["content-range"]?.match(/\/(\d+)$/)?.[1];
  void serial(() => collect(details.tabId, {url: details.url, mime, disposition: headers["content-disposition"], size: Number(total || headers["content-length"]) || 0}));
}, {urls: ["http://*/*", "https://*/*"]}, ["responseHeaders"]);

chrome.tabs.onUpdated.addListener((tabId, change) => {
  if (change.status === "loading") void serial(async () => { await chrome.storage.session.remove(key(tabId)); await badge(tabId, 0); });
});
chrome.tabs.onRemoved.addListener(tabId => { void serial(() => chrome.storage.session.remove(key(tabId))); });

async function handle(message, sender) {
  if (message.type === "PAGE_METADATA" && sender.tab && sender.frameId === 0) {
    return serial(async () => {
      const config = await settings();
      if (!config.enabled || isBlocked(sender.tab.url, config)) return {ok: true};
      const data = (await chrome.storage.session.get(key(sender.tab.id)))[key(sender.tab.id)] || {items: [], pageUrl: sender.tab.url};
      data.pageMetadata = {title: String(message.title || "").trim().slice(0, 300), priority: Math.min(60, Math.max(20, Number(message.priority) || 20))};
      for (const item of data.items) Object.assign(item, suggestedName(item, data.pageMetadata, sender.tab.title));
      await chrome.storage.session.set({[key(sender.tab.id)]: data});
      return {ok: true};
    });
  }
  if (message.type === "FOUND" && sender.tab) {
    const items = Array.isArray(message.items) ? message.items.slice(0, 150) : [];
    return serial(async () => { for (const item of items) await collect(sender.tab.id, item); return {ok: true}; });
  }
  // Privileged operations are only available to extension pages.
  if (sender.tab || !sender.url?.startsWith(chrome.runtime.getURL(""))) throw new Error("无权执行此操作。");
  if (message.type === "LIST") {
    await queue;
    const config = await settings();
    const data = (await chrome.storage.session.get(key(message.tabId)))[key(message.tabId)] || {items: []};
    if (data.items.some(item => !item.nameVersion && ["hls", "dash"].includes(item.type))) {
      const tab = await chrome.tabs.get(message.tabId);
      data.items = data.items.map(item => !item.nameVersion && ["hls", "dash"].includes(item.type) ? {...item, ...suggestedName(item, data.pageMetadata, tab.title)} : item);
    }
    return { ...data, settings: config };
  }
  if (message.type === "CLEAR") return serial(async () => { await chrome.storage.session.remove(key(message.tabId)); await badge(message.tabId, 0); return {ok: true}; });
  if (message.type === "DOWNLOAD" || message.type === "STREAM") {
    await queue;
    const data = (await chrome.storage.session.get(key(message.tabId)))[key(message.tabId)];
    const item = data?.items.find(i => i.id === message.id);
    if (!item) throw new Error("视频记录已失效，请重新扫描。");
    const downloadItem = {...item, title: String(message.title || "").trim() || item.title};
    if (message.type === "STREAM") {
      if (item.type !== "hls") throw new Error("只支持 HLS 处理。");
      if (!message.quality || !httpUrl(message.quality.url) || message.quality.audio) throw new Error("请先在弹窗中选择可下载的清晰度。");
      const job = crypto.randomUUID();
      const selectedVariant = {url: message.quality.url, resolution: String(message.quality.resolution || "原始清晰度"), bandwidth: Number(message.quality.bandwidth) || 0};
      const outputFormat = message.outputFormat === "ts" ? "ts" : "mp4";
      await chrome.storage.session.set({[`job:${job}`]: {...downloadItem, selectedVariant, outputFormat, autoStart: true}});
      await chrome.tabs.create({ url: chrome.runtime.getURL(`stream.html?job=${job}`) });
      return {ok: true};
    }
    const config = await settings();
    const downloadId = await chrome.downloads.download({url: item.url, filename: filename(downloadItem, config.folder), saveAs: config.saveAs, conflictAction: "uniquify"});
    return {ok: true, downloadId};
  }
  throw new Error("未知操作。");
}
chrome.runtime.onMessage.addListener((message, sender, respond) => {
  handle(message, sender).then(respond, error => respond({error: error.message}));
  return true;
});
